package warungaju;
import java.awt.*; import javax.swing.*; import javax.swing.table.DefaultTableModel;
public class ArusKasPanel extends JPanel {
    public ArusKasPanel(MainFrame f){setLayout(new BorderLayout(16,16));setBackground(MainFrame.LIGHT);setBorder(BorderFactory.createEmptyBorder(25,30,30,30));add(new JLabel("<html><h1>Prediksi Arus Kas</h1><font color='#60736b'>Proyeksi saldo berdasarkan tren data contoh</font></html>"),BorderLayout.NORTH);JPanel input=new JPanel(new FlowLayout(FlowLayout.LEFT,12,12));input.setBackground(Color.WHITE);JTextField saldo=UI.input("3500000"),in=UI.input("1250000"),out=UI.input("650000");JButton run=UI.button("Prediksi 6 Bulan");input.add(new JLabel("Saldo awal"));input.add(saldo);input.add(new JLabel("Pemasukan/bln"));input.add(in);input.add(new JLabel("Pengeluaran/bln"));input.add(out);input.add(run);DefaultTableModel m=new DefaultTableModel(new String[]{"Periode","Prediksi Pemasukan","Prediksi Pengeluaran","Saldo Akhir","Status"},0);JTable table=new JTable(m);UI.styleTable(table);JPanel body=new JPanel(new BorderLayout(12,12));body.setOpaque(false);body.add(input,BorderLayout.NORTH);body.add(new JScrollPane(table),BorderLayout.CENTER);add(body,BorderLayout.CENTER);run.addActionListener(e->{m.setRowCount(0);try{for(PrediksiArusKas.Month x:new PrediksiArusKas().prediksi(Double.parseDouble(saldo.getText()),Double.parseDouble(in.getText()),Double.parseDouble(out.getText()),6))m.addRow(new Object[]{x.nama,UI.money(x.pemasukan),UI.money(x.pengeluaran),UI.money(x.saldo),x.saldo<0?"DEFISIT":"Aman"});}catch(NumberFormatException ex){JOptionPane.showMessageDialog(this,"Input harus angka.","Validasi",JOptionPane.WARNING_MESSAGE);}});}
}
